/**
 * ETF 申赎净流入核心逻辑（Vite 中间件 / Worker 共用）
 * 口径：净流入(亿) ≈ Δ总份额(份) × 当日收盘价 / 1e8
 * 份额来源：上交所 ETF 规模接口（万份）；价格来源：东财日 K 收盘价（近似净值）
 */

export const DEFAULT_ETF_CODE = '510300'
export const DEFAULT_ETF_NAME = '沪深300ETF华泰柏瑞'
export const DEFAULT_ETF_SECID = '1.510300'

export type EtfFlowDay = {
  date: string
  /** 收盘价（元），作净值近似 */
  close: number
  /** 总份额（万份），上交所口径 */
  shareWan: number
  /** 当日净流入（亿元）；首日无前值时为 null */
  netInflowYi: number | null
}

export type EtfFlowResult = {
  code: string
  name: string
  asOf: string
  latestNetInflowYi: number | null
  latestShareWan: number | null
  series: EtfFlowDay[]
  /** 份额尚未披露的最近交易日（常见为当日 T+1） */
  pendingDates: string[]
  note: string
}

export type EtfFlowDeps = {
  /** 拉取日 K：返回按日期升序的 {date, close} */
  fetchKlines: (secid: string, limit: number) => Promise<Array<{ date: string; close: number }>>
  /** 拉取某日该 ETF 总份额（万份）；无数据返回 null */
  fetchShareWan: (code: string, date: string) => Promise<number | null>
  /** 可选缓存：已有则跳过上游 */
  getCachedShareWan?: (code: string, date: string) => Promise<number | null | undefined>
  setCachedShareWan?: (code: string, date: string, shareWan: number) => Promise<void>
  concurrency?: number
}

async function mapPool<T, R>(
  items: T[],
  concurrency: number,
  worker: (item: T) => Promise<R>,
): Promise<R[]> {
  const out: R[] = new Array(items.length)
  let i = 0
  async function run() {
    while (i < items.length) {
      const idx = i++
      out[idx] = await worker(items[idx])
    }
  }
  const n = Math.min(concurrency, Math.max(1, items.length))
  await Promise.all(Array.from({ length: n }, () => run()))
  return out
}

export async function buildEtfFlowSeries(
  opts: {
    code?: string
    name?: string
    secid?: string
    days?: number
  },
  deps: EtfFlowDeps,
): Promise<EtfFlowResult> {
  const code = opts.code || DEFAULT_ETF_CODE
  const name = opts.name || DEFAULT_ETF_NAME
  const secid = opts.secid || DEFAULT_ETF_SECID
  const days = Math.min(Math.max(opts.days ?? 90, 10), 250)
  const concurrency = deps.concurrency ?? 8

  const klines = await deps.fetchKlines(secid, days)
  if (klines.length < 2) {
    throw new Error('ETF 日线不足，无法计算净流入')
  }

  const shareByDate = new Map<string, number>()
  const pendingDates: string[] = []

  await mapPool(klines, concurrency, async (row) => {
    const cached = deps.getCachedShareWan
      ? await deps.getCachedShareWan(code, row.date)
      : undefined
    if (typeof cached === 'number' && Number.isFinite(cached)) {
      shareByDate.set(row.date, cached)
      return
    }
    const wan = await deps.fetchShareWan(code, row.date)
    if (wan == null || !Number.isFinite(wan)) {
      pendingDates.push(row.date)
      return
    }
    shareByDate.set(row.date, wan)
    if (deps.setCachedShareWan) await deps.setCachedShareWan(code, row.date, wan)
  })

  const series: EtfFlowDay[] = []
  for (let i = 0; i < klines.length; i++) {
    const { date, close } = klines[i]
    const shareWan = shareByDate.get(date)
    if (shareWan == null) continue
    let netInflowYi: number | null = null
    if (i > 0) {
      const prev = klines[i - 1]
      const prevShare = shareByDate.get(prev.date)
      if (prevShare != null) {
        // 万份 → 份，× 收盘价 → 元，/1e8 → 亿元
        netInflowYi = Math.round(((shareWan - prevShare) * 10000 * close) / 1e8 * 100) / 100
      }
    }
    series.push({ date, close, shareWan, netInflowYi })
  }

  const last = series[series.length - 1]
  return {
    code,
    name,
    asOf: last?.date ?? klines[klines.length - 1].date,
    latestNetInflowYi: last?.netInflowYi ?? null,
    latestShareWan: last?.shareWan ?? null,
    series,
    pendingDates: pendingDates.sort(),
    note:
      '净流入 ≈ 日份额变动 × 收盘价；份额来自上交所，常晚一天披露。单只 ETF 申赎净额是大资金代理指标，非官方「国家队」口径。',
  }
}

export function parseEmKlines(payload: {
  data?: { klines?: string[] } | null
}): Array<{ date: string; close: number }> {
  const lines = payload.data?.klines ?? []
  const out: Array<{ date: string; close: number }> = []
  for (const line of lines) {
    const parts = line.split(',')
    if (parts.length < 3) continue
    const date = parts[0]
    const close = Number(parts[2])
    if (!date || !Number.isFinite(close)) continue
    out.push({ date, close })
  }
  return out
}

export function parseSseShareWan(
  payload: { result?: Array<Record<string, string>> | null },
  code: string,
): number | null {
  const rows = payload.result ?? []
  const hit = rows.find((r) => r.SEC_CODE === code)
  if (!hit?.TOT_VOL) return null
  const wan = Number(hit.TOT_VOL)
  return Number.isFinite(wan) ? wan : null
}
